/* eslint-disable */
import React from "react";
import { Link, useLocation } from "react-router-dom";
import DashIcon from "components/icons/DashIcon";
// chakra imports

export function SidebarLinks(props) {
  // Chakra color mode
  let location = useLocation();

  const { routes } = props;

  // verifies if routeName is the one active (in browser input)
  const activeRoute = (routeName) => {
    return location.pathname.includes(routeName);
  };

  const createLinks = (routes) => {
    // Get logged-in user
    const userStr = sessionStorage.getItem("dayal_user");
    const user = userStr ? JSON.parse(userStr) : null;
    const isAdmin = user?.role === "Admin";
    const isCRO = user?.role === "CRO";
    const permissions = user?.permissions || {};

    return routes.map((route, index) => {
      // Check if user has permission to see this route
      let hasPermission = false;
      
      if (isAdmin) {
        hasPermission = true;
      } else if (isCRO && route.layout === "/admin") {
        const allowedForCRO = [
          "Dashboard",
          "Leads",
          "Clients",
          "Design & Legal Services",
          "Execution Projects",
          "Tasks",
          "Follow Ups",
          "Profile Settings"
        ];
        if (allowedForCRO.includes(route.name)) hasPermission = true;
      } else if (route.layout === "/admin") {
        const allowedForEmployees = [
           "Dashboard", 
           "Leads", 
           "Clients", 
           "Design & Legal Services", 
           "Execution Projects", 
           "Tasks",
           "Follow Ups",
           "Profile Settings"
        ];
        if (allowedForEmployees.includes(route.name)) {
           hasPermission = true;
        }
      }

      // Hide admin routes if no permission
      if (route.layout === "/admin" && !hasPermission) {
        return null;
      }

      if (
        route.layout === "/admin" ||
        route.layout === "/rtl"
      ) {
        return (
          <Link key={index} to={route.layout + "/" + route.path}>
            <div className="relative mb-3 flex hover:cursor-pointer">
              <li
                className="my-[3px] flex cursor-pointer items-center px-8"
                key={index}
              >
                <span
                  className={`${
                    activeRoute(route.path) === true
                      ? "font-bold text-brand-500 dark:text-white"
                      : "font-medium text-gray-600"
                  }`}
                >
                  {route.icon ? route.icon : <DashIcon />}{" "}
                </span>
                <p
                  className={`leading-1 ml-4 flex ${
                    activeRoute(route.path) === true
                      ? "font-bold text-navy-700 dark:text-white"
                      : "font-medium text-gray-600"
                  }`}
                >
                  {route.name}
                </p>
              </li>
              {activeRoute(route.path) ? (
                <div class="absolute right-0 top-px h-9 w-1 rounded-lg bg-brand-500 dark:bg-brand-400" />
              ) : null}
            </div>
          </Link>
        );
      }
    });
  };
  // BRAND
  return createLinks(routes);
}

export default SidebarLinks;
